<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Holder\UserProfileZoneinfoAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileZoneinfoAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserProfileZoneinfoAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getZoneinfo returns null on a freshly created holder.
     */
    public function testZoneinfoNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileZoneinfoAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isZoneinfoAssigned());
        $this->assertNull($holder->getZoneinfo());
    }
}
class ImplWithUserProfileZoneinfoAttributeHolderUnitTest
{
    use UserProfileZoneinfoAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedZoneinfoRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultZoneinfo();
    }
}
